#!/usr/bin/env bash
# P0-D: provision a REAL upstream Laravel app for smoke tests.
# The app itself is never modified (deployment config only: .env already
# generated by create-project). Idempotent: skips when provisioned.
set -euo pipefail
DIR="${PHPX_LARAVEL_DIR:-data/smoke/laravel}"
if [ -f "$DIR/public/index.php" ] && [ -f "$DIR/vendor/autoload.php" ] && [ -f "$DIR/.env" ]; then
  echo "[laravel-smoke] already provisioned at $DIR"
  exit 0
fi
export COMPOSER_NO_INTERACTION=1 COMPOSER_ALLOW_SUPERUSER=1
command -v composer >/dev/null || { echo "composer not found in PATH (see docs/operations/linux-prerequisites.md)"; exit 2; }
command -v php >/dev/null || { echo "php not found in PATH"; exit 2; }
if [ -e "$DIR" ]; then
  echo "[laravel-smoke] incomplete install at $DIR, recreating..."
  rm -rf "$DIR"
fi
composer create-project 'laravel/laravel:^12.0' "$DIR" --prefer-dist --no-progress --no-interaction
chmod -R u+rwX "$DIR/storage" "$DIR/bootstrap/cache" 2>/dev/null || true
echo "[laravel-smoke] ready at $DIR ($(php "$DIR/artisan" --version 2>/dev/null || echo version-unknown))"
